function cap(n){return 800+n.tiles.size*12+n.city*1800}function allied(a,b){if(a<0||b<0)return false;return mode==='teams'&&nations[a].team===nations[b].team||(alliances.get([a,b].sort((x,y)=>x-y).join(':'))||0)>time}function edge(id,target){let a=[],seen=new Set();for(const t of nations[id].tiles)for(const q of neighbors(t))if(owner[q]===target&&!seen.has(q)){seen.add(q);a.push(q)}return a}
